```javascript
const chunks = [];

process.stdin.on('data', (chunk) => chunks.push(chunk));
process.stdin.on('end', () => {
    const tokens = chunks
        .join('')
        .trim()
        .split(/\s+/)
        .filter((t) => t.length > 0);

    let idx = 0;
    const R = parseInt(tokens[idx++], 10);
    const N = parseInt(tokens[idx++], 10);

    // Menor preço encontrado para cada tipo de fruta
    const minPrice = new Map();
    for (let i = 0; i < N; i++) {
        const T = parseInt(tokens[idx++], 10);
        const P = parseInt(tokens[idx++], 10);
        const cur = minPrice.get(T);
        if (cur === undefined || P < cur) minPrice.set(T, P);
    }

    // Para maximizar tipos distintos, basta considerar o menor preço de cada tipo
    const prices = Array.from(minPrice.values()).sort((a, b) => a - b);

    let total = 0;
    let count = 0;
    for (const p of prices) {
        if (total + p <= R) {
            total += p;
            count++;
        } else {
            break;
        }
    }

    process.stdout.write(String(count) + '\n');
});
